{
  "scenario_f_case_2": {
    "input_group": [
      { "id": 7, "index": 0, "category": "correctness" },
      { "id": 8, "index": 1, "category": "cleanup" }
    ],
    "grouping_contract": "One location-group may contain different categories; category differences must not split or reject this group.",
    "acceptance_contract": {
      "required_rows": 2,
      "allowed_indexes": [0, 1],
      "index_type": "number",
      "index_must_be_integer": true,
      "candidate_pairing": "index 0 must identify source id 7; index 1 must identify source id 8",
      "cardinality": "exactly one candidate row for each source row"
    },
    "transitions": [
      {
        "fixture": "valid index 0 paired with valid index 1",
        "validation": "accept",
        "state_transition": ["group:pending", "group:validated", "group:survives"],
        "survivors": [7, 8],
        "retry": "none"
      },
      {
        "fixture": "missing index",
        "validation": "reject: index is required",
        "state_transition": ["group:pending", "group:discarded", "group:retrying_once", "group:discarded", "group:stopped"],
        "survivors": [],
        "retry": "one retry only"
      },
      {
        "fixture": "duplicate index",
        "validation": "reject: does not provide one row for each source index",
        "state_transition": ["group:pending", "group:discarded", "group:retrying_once", "group:discarded", "group:stopped"],
        "survivors": [],
        "retry": "one retry only"
      },
      {
        "fixture": "index 1.5",
        "validation": "reject: index must be an actual integer",
        "state_transition": ["group:pending", "group:discarded", "group:retrying_once", "group:discarded", "group:stopped"],
        "survivors": [],
        "retry": "one retry only"
      },
      {
        "fixture": "index 2",
        "validation": "reject: index out of range",
        "state_transition": ["group:pending", "group:discarded", "group:retrying_once", "group:discarded", "group:stopped"],
        "survivors": [],
        "retry": "one retry only"
      },
      {
        "fixture": "index \"0\"",
        "validation": "reject: numeric strings are not integer indexes",
        "state_transition": ["group:pending", "group:discarded", "group:retrying_once", "group:discarded", "group:stopped"],
        "survivors": [],
        "retry": "one retry only"
      },
      {
        "fixture": "mismatched source-id/index pair",
        "validation": "reject: index-to-source pairing must be exact",
        "state_transition": ["group:pending", "group:discarded", "group:retrying_once", "group:discarded", "group:stopped"],
        "survivors": [],
        "retry": "one retry only"
      }
    ]
  },
  "scenario_f_case_3": {
    "contract": "A materially new replacement for the same defect/category is valid refinement, not a duplicate merely because the defect/category is the same.",
    "transitions": [
      {
        "actor": "initial verifier",
        "source_id": 7,
        "event": "proposes materially new same-category replacement",
        "state_transition": ["replacement#1:proposed", "replacement#1:accepted"],
        "active_order": ["replacement#1(source:7)"],
        "disposition": { "replacement#1": "active" }
      },
      {
        "actor": "sweep verifier",
        "source_id": 9,
        "event": "proposes materially new same-category replacement",
        "state_transition": ["replacement#2:proposed", "replacement#2:accepted"],
        "active_order": ["replacement#1(source:7)", "replacement#2(source:9)"],
        "disposition": {
          "replacement#1": "retained",
          "replacement#2": "active"
        }
      },
      {
        "actor": "replacement verifier",
        "source_id": "its verified replacement source",
        "event": "proposes another materially new replacement",
        "state_transition": ["replacement#3:proposed", "replacement#3:accepted"],
        "active_order": [
          "replacement#1(source:7)",
          "replacement#2(source:9)",
          "replacement#3"
        ],
        "disposition": {
          "replacement#1": "retained",
          "replacement#2": "retained",
          "replacement#3": "active"
        }
      }
    ],
    "id_rule": "Each accepted proposal receives a distinct state/candidate ID in proposal order. Source IDs remain provenance, not replacement identity; no replacement may overwrite a prior state solely due to same defect/category."
  },
  "scenario_f_case_5": {
    "transitions": [
      {
        "fixture": "finder returns zero candidates",
        "state_transition": ["finder:zero", "pipeline:valid_zero", "pipeline:complete"],
        "retry": "none",
        "survivors": []
      },
      {
        "fixture": "sweep returns zero candidates",
        "state_transition": ["sweep:zero", "pipeline:valid_zero", "pipeline:complete"],
        "retry": "none",
        "survivors": []
      },
      {
        "fixture": "verifier returns empty for a deliberate-zero fixture",
        "state_transition": ["group:deliberate_zero", "verifier:empty_accepted", "pipeline:complete"],
        "retry": "none",
        "survivors": []
      },
      {
        "fixture": "verifier returns empty for a nonempty group",
        "state_transition": ["group:nonempty_pending", "verifier:incomplete_empty", "group:discarded", "group:retrying_once", "verifier:incomplete_empty", "group:discarded", "group:stopped"],
        "retry": "one retry only",
        "survivors": []
      }
    ],
    "terminal_contract": "No candidate survives any nonempty-group empty-verifier failure; a valid deliberate zero is not treated as an incomplete group."
  }
}

